export const QUESTIONS_306A = [
  // BLOCK A: Occupational Skills & Safety (22)
  {id:1,cat:"A",q:"What is the minimum trench depth that requires shoring or sloping?",opts:["0.6m (2 ft)","1.2m (4 ft)","1.8m (6 ft)","2.4m (8 ft)"],ans:1,exp:"OHSA requires shoring, sloping, or a trench box when the trench exceeds 1.2m (4 ft) deep. Soil type determines the required slope angle.",type:"recall"},
  {id:2,cat:"A",q:"Before cutting into an existing pipe, what must be done?",opts:["Apply Teflon tape","Identify pipe contents, shut off supply, and drain the system","Start cutting immediately","Call the inspector"],ans:1,exp:"Always identify what's in the pipe (water, gas, sewage, chemicals), isolate the supply, drain the system, and verify it's depressurized before cutting.",type:"procedure"},
  {id:3,cat:"A",q:"What PPE is required when soldering copper pipe?",opts:["No PPE needed","Safety glasses, heat-resistant gloves, and adequate ventilation","Steel-toed boots only","Hard hat only"],ans:1,exp:"Soldering requires eye protection from flux splatter, heat-resistant gloves, and ventilation to avoid inhaling flux fumes (especially with lead-free solder).",type:"recall"},
  {id:4,cat:"A",q:"The National Plumbing Code of Canada is designated as:",opts:["CSA B149","NPC 2020 (based on NRC model code)","CEC Section 26","ASHRAE 90.1"],ans:1,exp:"The National Plumbing Code of Canada (NPC) is the model code published by NRC. Provinces adopt it with local amendments.",type:"recall"},
  {id:5,cat:"A",q:"A plumbing permit is required for which of the following?",opts:["Replacing a faucet cartridge","Any new installation, alteration, or extension of a plumbing system","Unclogging a drain","Replacing a toilet flapper"],ans:1,exp:"Permits are required for new installations, alterations, or extensions of plumbing systems. Routine maintenance and repairs (like replacing cartridges) generally don't require permits.",type:"recall"},
  {id:6,cat:"A",q:"Grade (slope) is measured using what tool?",opts:["Tape measure only","Spirit level with a grade indicator or laser level","Plumb bob","Square"],ans:1,exp:"A spirit level with grade markings (1/4\" per foot, etc.) or a laser level with grade capability is used to establish proper pipe slope for drainage.",type:"recall"},
  {id:7,cat:"A",q:"What does a plumber use to cut cast iron soil pipe?",opts:["Hacksaw only","Snap cutter (chain cutter) or angle grinder with abrasive blade","Pipe threader","Tube cutter"],ans:1,exp:"Snap cutters use a chain of cutting wheels that tighten around the pipe and snap it cleanly. Angle grinders with abrasive blades also work but create more dust.",type:"recall"},
  {id:8,cat:"A",q:"When reading an isometric drawing, vertical pipes are drawn at:",opts:["Horizontal","30° from horizontal","45° from horizontal","90° vertical"],ans:2,exp:"In isometric plumbing drawings, vertical pipes are drawn at true vertical, and horizontal pipes are drawn at 30° from horizontal. This creates the 3D illusion.",type:"recall"},
  {id:9,cat:"A",q:"The maximum weight a plumber should lift alone per OHSA guidelines is approximately:",opts:["50 lbs (23 kg)","100 lbs","200 lbs","No limit"],ans:0,exp:"General ergonomic guidelines suggest a maximum of about 23kg (50 lbs) for individual lifting. Heavier items require mechanical assistance or team lifting.",type:"recall"},
  {id:10,cat:"A",q:"What gas is used with oxygen for brazing copper?",opts:["Propane only","Acetylene or MAP gas","Natural gas","Helium"],ans:1,exp:"Acetylene with oxygen produces the hottest flame for brazing. MAP/Pro gas works for most brazing. Propane is usually insufficient for brazing larger copper pipe.",type:"recall"},
  {id:11,cat:"A",q:"When installing underground piping, what provides protection from backfill damage?",opts:["Paint","Proper bedding material (sand/gravel) and careful backfill compaction","Wrapping in newspaper","Nothing needed"],ans:1,exp:"Proper bedding (typically 150mm of sand/gravel) under and around the pipe, followed by careful backfill without large rocks, protects underground piping from damage and settling.",type:"procedure"},
  {id:12,cat:"A",q:"What is the standard rough-in height for a water closet (toilet) flange above the finished floor?",opts:["50mm above","Flush with or slightly above finished floor","100mm below","200mm above"],ans:1,exp:"The closet flange should sit flush with or slightly above (max 6mm) the finished floor surface. Too high or too low causes leaking at the wax ring seal.",type:"recall"},
  {id:13,cat:"A",q:"An offset is calculated using which mathematical relationship?",opts:["Addition only","The Pythagorean theorem or trigonometry (travel = offset ÷ sine of fitting angle)","Multiplication only","Division only"],ans:1,exp:"Pipe offset calculations use trigonometry: Travel = Offset ÷ sin(angle). For a 45° offset: Travel = Offset × 1.414. For 22.5°: Travel = Offset × 2.613.",type:"critical"},
  {id:14,cat:"A",q:"What is the travel multiplier for a 45° offset?",opts:["1.000","1.414","2.000","2.613"],ans:1,exp:"45° offset: Travel = Offset × 1.414 (which is √2). This is the most commonly used offset in plumbing. Memorize: 45° = 1.414, 22.5° = 2.613, 60° = 1.155.",type:"critical"},
  {id:15,cat:"A",q:"A transit level is used on site to:",opts:["Cut pipe","Establish elevations and grades for underground piping","Solder joints","Thread pipe"],ans:1,exp:"Transit levels establish elevation benchmarks and verify pipe grades. The instrument shoots a level line of sight; a grade rod reads elevations at various points.",type:"recall"},
  {id:16,cat:"A",q:"Which type of joint is used for underground cast iron pipe?",opts:["Soldered","No-hub (banded coupling) or hub-and-spigot with gasket","Threaded","Glued"],ans:1,exp:"No-hub couplings (stainless steel band over neoprene gasket) are standard for cast iron. Hub-and-spigot with compression gaskets are used for some underground applications.",type:"recall"},
  {id:17,cat:"A",q:"What is the minimum depth for water supply piping below grade to prevent freezing in most Canadian jurisdictions?",opts:["300mm (12\")","Minimum frost depth per local code (typically 1.2m-2.4m depending on region)","150mm (6\")","Any depth"],ans:1,exp:"Water lines must be below the local frost depth, which varies across Canada from about 1.2m in southern Ontario to 2.4m+ in northern regions. Local codes specify exact depths.",type:"recall"},
  {id:18,cat:"A",q:"Fire stopping is required when plumbing pipe penetrates:",opts:["Any wall","A fire-rated assembly (floor, ceiling, or wall)","Only exterior walls","Only basement walls"],ans:1,exp:"All penetrations through fire-rated assemblies must be sealed with approved firestop materials to maintain the fire rating. This prevents fire and smoke spread between compartments.",type:"recall"},
  {id:19,cat:"A",q:"What is the purpose of a plumbing inspection?",opts:["Increase project cost","Verify installation complies with code requirements for health and safety","Slow down the project","Only required for commercial"],ans:1,exp:"Inspections verify code compliance to protect public health (safe drinking water, proper sewage disposal) and safety (gas piping integrity, structural concerns).",type:"recall"},
  {id:20,cat:"A",q:"When using a powder-actuated tool to attach hangers to concrete, what safety measure is critical?",opts:["No safety needed","Wear hearing and eye protection, check for embedded utilities, and follow manufacturer procedures","Wear only gloves","Use maximum charge always"],ans:1,exp:"Powder-actuated tools are essentially firearms. Require hearing/eye protection, check for rebar/electrical/plumbing behind the concrete, use correct charge strength, and follow all manufacturer safety procedures.",type:"procedure"},
  {id:21,cat:"A",q:"A rolling offset involves calculating:",opts:["Only horizontal offset","Both horizontal and vertical offset simultaneously using 3D trigonometry","Only vertical offset","No calculation needed"],ans:1,exp:"A rolling offset changes direction both horizontally and vertically. True travel = √(horizontal offset² + vertical offset²) × fitting multiplier. This is the hardest offset calculation on the exam.",type:"critical"},
  {id:22,cat:"A",q:"The plumbing code requires access panels for:",opts:["All pipe","Concealed valves, cleanouts, and equipment requiring maintenance","Decorative purposes","Insulation access only"],ans:1,exp:"Access panels must be provided for concealed shut-off valves, cleanouts, trap primers, backflow preventers, and any equipment requiring inspection or maintenance.",type:"recall"},

  // BLOCK B: Water Supply & Distribution (25)
  {id:23,cat:"B",q:"The maximum velocity recommended for hot water distribution piping is:",opts:["1.5 m/s (5 fps)","2.4 m/s (8 fps)","4.5 m/s (15 fps)","0.3 m/s (1 fps)"],ans:1,exp:"Hot water piping: max ~2.4 m/s (8 fps). Exceeding this causes erosion, noise (water hammer), and premature fitting/valve wear. Cold water can go slightly higher.",type:"recall"},
  {id:24,cat:"B",q:"What is the purpose of a pressure reducing valve (PRV)?",opts:["Increase pressure","Reduce incoming water pressure to a safe level (typically 550 kPa / 80 PSI max)","Filter water","Heat water"],ans:1,exp:"PRVs reduce high street pressure to safe building levels. Code typically limits building pressure to 550 kPa (80 PSI). High pressure damages fixtures, causes noise, and wastes water.",type:"recall"},
  {id:25,cat:"B",q:"Thermal expansion in a closed hot water system is controlled by:",opts:["Opening a faucet","An expansion tank","A larger water heater","A check valve"],ans:1,exp:"When water heats, it expands. In a closed system (with check valve or PRV), an expansion tank absorbs the increased volume, preventing dangerous pressure buildup.",type:"recall"},
  {id:26,cat:"B",q:"Cross-connection is defined as:",opts:["A tee fitting","Any connection between potable water and a non-potable source","A cross fitting","Two pipes crossing"],ans:1,exp:"Cross-connections are the #1 threat to potable water safety. Any physical connection that could allow contaminants to flow back into the drinking water supply.",type:"recall"},
  {id:27,cat:"B",q:"What type of backflow preventer is required for high-hazard connections?",opts:["Atmospheric vacuum breaker","Reduced pressure zone (RPZ) assembly","Dual check valve","Hose bib vacuum breaker"],ans:1,exp:"RPZ assemblies are required for high-hazard connections (boilers, chemical systems, irrigation with chemicals). They have a relief valve that dumps to atmosphere if both checks fail.",type:"recall"},
  {id:28,cat:"B",q:"The minimum pipe size for a residential water service in most jurisdictions is:",opts:["1/2\" (12mm)","3/4\" (19mm)","1\" (25mm)","1-1/2\" (38mm)"],ans:1,exp:"Most codes require minimum 3/4\" (19mm) for residential water service. Larger homes or those with high fixture counts may need 1\" or larger based on demand calculations.",type:"recall"},
  {id:29,cat:"B",q:"Water hammer is caused by:",opts:["Low pressure","Sudden stoppage of water flow (quick-closing valves) creating a pressure shockwave","Hot water","Dirty water"],ans:1,exp:"Rapid valve closure creates a pressure wave that travels through the piping at the speed of sound in water (~1400 m/s). Water hammer arrestors or air chambers absorb the shock.",type:"recall"},
  {id:30,cat:"B",q:"PEX tubing connections are made using:",opts:["Soldering","Crimp rings, expansion fittings, or push-fit connections","Threading","Cement/primer"],ans:1,exp:"PEX uses: crimp rings (copper) with crimp tool, cold expansion with ProPEX fittings, or push-fit (SharkBite). No heat, no solvents. Each method requires specific tools.",type:"recall"},
  {id:31,cat:"B",q:"What is the fixture unit value for a standard bathtub?",opts:["1 FU","2 FU","3 FU","4 FU"],ans:1,exp:"A standard bathtub = 2 fixture units. Fixture unit values are used to size water supply piping, DWV piping, and determine peak demand. Values are in NPC tables.",type:"recall"},
  {id:32,cat:"B",q:"The minimum hot water temperature to prevent Legionella bacteria is:",opts:["40°C (104°F)","60°C (140°F) at the tank","80°C (176°F)","Room temperature"],ans:1,exp:"Water heaters should maintain 60°C (140°F) minimum to kill Legionella. Anti-scald mixing valves then temper it to 49°C (120°F) max at fixtures to prevent burns.",type:"recall"},
  {id:33,cat:"B",q:"Copper pipe type L (identified by blue marking) is used for:",opts:["DWV only","General purpose water distribution (most common for interior supply)","Gas piping only","Refrigeration only"],ans:1,exp:"Type L (blue) is standard for water supply. Type K (green) is heavier for underground. Type M (red) is lighter, used where codes permit. Type DWV is thin wall for drainage.",type:"recall"},
  {id:34,cat:"B",q:"When soldering copper, the joint must be cleaned and fluxed because:",opts:["For appearance","Flux removes oxides and promotes capillary action of solder into the joint","It's optional","To colour the joint"],ans:1,exp:"Clean, oxide-free surfaces allow solder to bond metallurgically. Flux dissolves remaining oxides during heating and promotes capillary flow. Dirty joints = failed joints.",type:"recall"},
  {id:35,cat:"B",q:"A water supply system is tested at what pressure?",opts:["Operating pressure only","100 PSI (690 kPa) or as required by local code for specified duration","10 PSI","500 PSI"],ans:1,exp:"Typical hydrostatic test: 100 PSI (or 1.5× operating pressure) for a minimum duration (often 2 hours). No pressure drop = passed. Local codes specify exact requirements.",type:"recall"},
  {id:36,cat:"B",q:"What is the purpose of a tempering valve at a water heater?",opts:["Increase temperature","Mix hot and cold water to deliver safe temperature (49°C/120°F max) at fixtures","Filter water","Increase pressure"],ans:1,exp:"Tempering valves blend hot (60°C storage) with cold water to deliver a safe 49°C (120°F) maximum to fixtures, preventing scalding while maintaining Legionella-killing storage temperature.",type:"recall"},
  {id:37,cat:"B",q:"The minimum air gap for a residential faucet above the flood rim of a sink is:",opts:["No gap required","25mm (1\") or 2× the faucet outlet diameter, whichever is greater","50mm","100mm"],ans:1,exp:"An air gap is the simplest backflow prevention. The faucet outlet must be above the flood level rim by at least 25mm or 2× the outlet diameter to prevent backsiphonage.",type:"recall"},
  {id:38,cat:"B",q:"CPVC pipe is joined using:",opts:["Heat fusion","Solvent cement (primer and cement specific to CPVC)","Compression fittings only","Solder"],ans:1,exp:"CPVC uses a two-step solvent welding process: primer (softens and cleans) then CPVC-specific cement (chemically fuses pipe to fitting). Regular PVC cement must NOT be used on CPVC.",type:"procedure"},
  {id:39,cat:"B",q:"Dielectric unions are required where:",opts:["Any pipe connection","Dissimilar metals are joined (copper to steel) to prevent galvanic corrosion","Same metals meet","Plastic to plastic"],ans:1,exp:"Dielectric unions electrically isolate dissimilar metals (copper/steel) to prevent galvanic corrosion. Without isolation, the less noble metal (steel) corrodes rapidly.",type:"recall"},
  {id:40,cat:"B",q:"Water supply pipe sizing is determined by:",opts:["Guessing","Total fixture unit count, developed length, available pressure, and elevation changes","Pipe colour","Building age"],ans:1,exp:"Sizing considers: total fixture units (demand), total developed length including equivalent lengths of fittings, available pressure at the meter, elevation (0.43 PSI per foot of rise), and minimum pressure at highest fixture.",type:"procedure"},
  {id:41,cat:"B",q:"What material is NOT suitable for hot water distribution over 60°C?",opts:["Copper","PVC (maximum rated temperature ~60°C)","CPVC","PEX"],ans:1,exp:"Standard PVC (Schedule 40) is rated to approximately 60°C (140°F) and derates significantly with heat. It's for cold water and DWV only. CPVC, copper, and PEX handle hot water.",type:"recall"},
  {id:42,cat:"B",q:"A recirculation pump in a hot water system provides:",opts:["Increased pressure","Reduced wait time for hot water at distant fixtures by continuously circulating","Filtration","Backflow prevention"],ans:1,exp:"Recirc pumps keep hot water moving through the system so users don't wait for hot water. Reduces water waste. Timer or temperature-controlled operation saves energy.",type:"recall"},
  {id:43,cat:"B",q:"The maximum length of a dead-end water line (dead leg) should be limited to prevent:",opts:["Nothing","Stagnation and bacterial growth (Legionella)","Pipe freezing only","Noise"],ans:1,exp:"Dead legs allow water to stagnate, creating conditions for Legionella and other bacteria. Maximum dead leg length should be minimized — some standards say 2× pipe diameter max.",type:"recall"},
  {id:44,cat:"B",q:"When installing water piping in exterior walls, what protection is needed?",opts:["None","Insulation to prevent freezing, and keep pipes on the warm side of insulation","Paint the pipe","Use copper only"],ans:1,exp:"Water pipes in exterior walls must be insulated and positioned on the warm (interior) side of wall insulation to prevent freezing. Heat trace may be needed in extreme cold zones.",type:"procedure"},
  {id:45,cat:"B",q:"Ball valves are preferred over gate valves for water supply because:",opts:["Cheaper only","Quarter-turn operation, full-port flow, less prone to failure, and visual open/close indication","They're blue","They're smaller"],ans:1,exp:"Ball valves: 1/4 turn (fast), full bore (low restriction), reliable long-term, handle dirty water better, and the lever position shows open/closed at a glance.",type:"recall"},
  {id:46,cat:"B",q:"A booster pump is required when:",opts:["Always","Building height or distance causes pressure to drop below minimum fixture requirements","Water is too hot","Pipes are too large"],ans:1,exp:"When municipal pressure is insufficient to supply upper floors (losing ~0.43 PSI per foot of elevation), booster pumps maintain adequate pressure throughout the building.",type:"recall"},
  {id:47,cat:"B",q:"What is the maximum fixture supply line length for a 3/8\" tube to a lavatory?",opts:["No limit","As specified by code — typically limited to maintain adequate flow and pressure","1 metre","10 metres"],ans:1,exp:"Fixture supply tubes (3/8\" or 1/2\") have length limitations based on the required flow rate and acceptable pressure drop. Longer runs may need upsizing to 1/2\".",type:"recall"},

  // BLOCK C: Drain, Waste & Vent (DWV) (28)
  {id:48,cat:"C",q:"The minimum slope for a 3\" horizontal drain pipe is:",opts:["1/8\" per foot (1%)","1/4\" per foot (2%) for pipes 3\" and smaller","1/2\" per foot","No slope needed"],ans:1,exp:"NPC: pipes 3\" and smaller = 1/4\" per foot (2%). Pipes 4\" and larger = 1/8\" per foot (1%). Proper slope ensures solids are carried, preventing blockages.",type:"recall"},
  {id:49,cat:"C",q:"A P-trap holds water to:",opts:["Increase pressure","Prevent sewer gases from entering the building through the fixture drain","Filter debris","Regulate flow"],ans:1,exp:"The trap seal (water in the P-trap) acts as a barrier against sewer gases (hydrogen sulfide, methane, etc.) which are toxic and explosive. Minimum trap seal depth is 50mm (2\").",type:"recall"},
  {id:50,cat:"C",q:"What causes a trap to lose its seal (siphonage)?",opts:["Normal use","Insufficient venting creating negative pressure that pulls water out of the trap","Too much water","Trap is too large"],ans:1,exp:"Without proper venting, draining water creates negative pressure (vacuum) behind it that siphons the trap seal. The vent allows air in to equalize pressure and protect the seal.",type:"critical"},
  {id:51,cat:"C",q:"A cleanout must be installed at:",opts:["Every joint","Every change of direction, base of stacks, and at regular intervals per code","Only outdoors","Only at fixtures"],ans:1,exp:"Cleanouts required at: changes of direction, base of every stack, upstream end of horizontal runs, every 15m (50ft) of horizontal drain, and where the building drain exits.",type:"recall"},
  {id:52,cat:"C",q:"The maximum distance from a P-trap to its vent (trap arm length) for a 1-1/2\" pipe is:",opts:["1.5m (5 ft)","1.8m (6 ft)","3.0m (10 ft)","No limit"],ans:0,exp:"Trap arm length limits per NPC: 1-1/4\" = 750mm, 1-1/2\" = 1.5m, 2\" = 2.4m, 3\" = 3.0m, 4\" = 3.6m. Exceeding these causes trap siphonage.",type:"critical"},
  {id:53,cat:"C",q:"A wet vent serves as both a:",opts:["Drain and water supply","Vent and a drain pipe simultaneously for limited fixtures","Vent and a gas line","Drain and a cleanout"],ans:1,exp:"Wet venting allows a vent pipe to also carry waste from limited upstream fixtures. Sizing must accommodate both functions. Common in residential bathroom groups.",type:"recall"},
  {id:54,cat:"C",q:"The minimum size for a building drain serving a home with a water closet is:",opts:["2\"","3\"","4\"","6\""],ans:1,exp:"Building drain must be minimum 3\" when serving a water closet (toilet). Some codes require 4\" for the building sewer (underground portion leaving the building).",type:"recall"},
  {id:55,cat:"C",q:"A vent terminating through a roof must extend at least:",opts:["50mm above roof","150mm (6\") above roof surface, and specific clearances from windows/air intakes","Flush with roof","300mm below roof"],ans:1,exp:"Vent terminals: minimum 150mm above roof (some codes say 300mm in snow regions). Must be specific distances from windows, doors, and air intakes to prevent sewer gas entry.",type:"recall"},
  {id:56,cat:"C",q:"ABS DWV pipe is joined using:",opts:["Heat fusion","ABS solvent cement (no primer required in most jurisdictions)","Compression fittings","Solder"],ans:1,exp:"ABS uses one-step cementing with ABS cement — no primer typically required (unlike PVC which needs primer). However, some jurisdictions require primer for ABS too. Check local code.",type:"recall"},
  {id:57,cat:"C",q:"The maximum number of fixture units on a 2\" horizontal branch is:",opts:["3 FU","6 FU","12 FU","21 FU"],ans:1,exp:"Per NPC drainage tables: 2\" horizontal branch = 6 FU max. Exceeding fixture unit limits causes surcharging and trap siphonage. Always size per the tables.",type:"recall"},
  {id:58,cat:"C",q:"What fitting is NOT allowed to change direction from horizontal to vertical in DWV?",opts:["90° long sweep elbow","Sanitary tee","Short-pattern 90° elbow (vent ell)","Wye with 45° elbow"],ans:2,exp:"Short-pattern 90° elbows (vent ells) are ONLY for vent piping. In drain piping, they create turbulence and block flow. Use long-sweep 90s, combos, or wye + 45° for drains.",type:"recall"},
  {id:59,cat:"C",q:"An air admittance valve (AAV) replaces:",opts:["A trap","A conventional vent terminal through the roof (where permitted by code)","A cleanout","A backflow preventer"],ans:1,exp:"AAVs allow air in during drainage (opens under negative pressure) but seal against sewer gases. They're used where conventional venting through the roof is impractical. Not allowed everywhere.",type:"recall"},
  {id:60,cat:"C",q:"A building trap (house trap) is:",opts:["Always required","A trap on the building drain (where required by local code) providing a second seal against sewer gas","An animal trap","Not related to plumbing"],ans:1,exp:"Building traps provide a water seal between the building drain and the public sewer. Not all jurisdictions require them. Where installed, a fresh air inlet is needed on the building side.",type:"recall"},
  {id:61,cat:"C",q:"The DWV system is tested using what method?",opts:["Air pressure only","Water test (10-foot head) or air test (35 kPa/5 PSI) for specified duration","Running water through it","Visual inspection only"],ans:1,exp:"Water test: fill system to 10-foot head of water (minimum) for 15 minutes minimum. Air test: 35 kPa (5 PSI) held for 15 minutes. No drop = passed. Local codes specify exact requirements.",type:"recall"},
  {id:62,cat:"C",q:"A sump pump with discharge into the sanitary sewer requires:",opts:["No special connections","A backwater valve to prevent sewage backup into the sump","Direct connection only","An air gap is optional"],ans:1,exp:"Backwater valves prevent sewage from backing up through the sump pump discharge during sewer surcharges. Some codes require an indirect connection (air gap) instead.",type:"procedure"},
  {id:63,cat:"C",q:"What is the purpose of a circuit vent?",opts:["Electrical connection","A single vent serving a group of fixtures on a horizontal branch (up to 8 fixtures)","A vent with a valve","A vent that circles back"],ans:1,exp:"Circuit venting provides a single vent connection for a series of fixtures on a horizontal branch (typically bathroom fixtures). It's an engineered alternative to individual venting.",type:"recall"},
  {id:64,cat:"C",q:"The minimum trap seal depth required by code is:",opts:["25mm (1\")","50mm (2\")","75mm (3\")","100mm (4\")"],ans:1,exp:"NPC requires minimum 50mm (2\") and maximum 100mm (4\") trap seal depth. Shallower = easier to siphon. Deeper = more friction and self-siphonage risk.",type:"recall"},
  {id:65,cat:"C",q:"What causes a double-trapped fixture to drain slowly?",opts:["Normal condition","Air lock between the two traps — the second trap prevents proper venting of the first","Pipe too large","Water too cold"],ans:1,exp:"Double trapping creates an air lock between the traps. Air can't escape, preventing proper drainage. This is why double trapping is prohibited by code.",type:"critical"},
  {id:66,cat:"C",q:"A stack vent is the extension of what pipe through the roof?",opts:["The water supply stack","The soil or waste stack above the highest branch connection","The vent stack only","The building drain"],ans:1,exp:"A stack vent is the portion of the soil/waste stack that extends above the highest horizontal drain connection. It terminates through the roof as the vent terminal.",type:"recall"},
  {id:67,cat:"C",q:"Grease interceptors are required for:",opts:["Residential kitchens","Commercial food service establishments to prevent grease from entering the sewer","All bathrooms","Laundry only"],ans:1,exp:"Commercial kitchens must have grease interceptors (traps) to prevent fats, oils, and grease from entering the sewer system, where they cause blockages and environmental damage.",type:"recall"},
  {id:68,cat:"C",q:"When installing PVC DWV pipe, the primer is:",opts:["Optional","Mandatory — it softens the pipe surface for proper solvent weld penetration","Only for appearance","Only used outdoors"],ans:1,exp:"PVC primer (purple) softens the pipe surface, allowing the cement to chemically penetrate and fuse the joint. Without primer, the joint is weak and may fail. Required by code.",type:"procedure"},
  {id:69,cat:"C",q:"A horizontal-to-horizontal change of direction in a drain line should use:",opts:["Short 90° ell","Two 45° elbows (or a long-sweep 90°)","A sanitary tee","A standard 90°"],ans:1,exp:"Horizontal-to-horizontal direction changes require two 45° elbows, a long-sweep 90°, or a combination wye + 45°. Short 90s and tees cause turbulence and blockages in horizontal runs.",type:"procedure"},
  {id:70,cat:"C",q:"The vent stack connects to the drainage system at the lowest point to:",opts:["Add structural support","Allow air circulation and convection to keep the vent system clear","Drain condensation","Collect debris"],ans:1,exp:"The vent stack connects at the base to create convection air flow. Warm air in the soil stack rises and draws fresh air in through the vent stack base, keeping the system ventilated.",type:"recall"},
  {id:71,cat:"C",q:"What is the maximum slope allowed for a drain pipe?",opts:["1/4\" per foot","No maximum — steeper is always better","One pipe diameter per 1.2m (code-dependent)","1\" per foot maximum"],ans:2,exp:"Too steep a slope causes liquids to outrun solids, leaving solids behind to create blockages. Most codes limit slope. General practice: don't exceed 1/4\" per foot for most applications.",type:"recall"},
  {id:72,cat:"C",q:"A backwater valve on a building drain prevents:",opts:["Forward flow","Sewage from backing up into the building during main sewer surcharging","Sewer gas only","Grease buildup"],ans:1,exp:"Backwater valves (check valves on the drain) prevent sewage from the overtaxed municipal sewer from flowing backwards into the building. Required by many jurisdictions.",type:"recall"},
  {id:73,cat:"C",q:"A combination wye and 1/8 bend fitting is used for:",opts:["Vertical to horizontal transitions only","Connecting a branch drain to a horizontal main drain (preferred directional fitting)","Vent connections only","Water supply only"],ans:1,exp:"The combo (wye + 1/8 bend) provides a smooth, gradual entry from branch to main drain. It's the preferred fitting for horizontal-to-horizontal drain connections.",type:"recall"},
  {id:74,cat:"C",q:"What is a soil stack?",opts:["A stack carrying only sink waste","A vertical drain pipe that receives discharge from water closets (toilets)","A vent-only pipe","A rainwater leader"],ans:1,exp:"A soil stack carries toilet (water closet) waste. A waste stack carries waste from fixtures other than toilets. In modern practice, the terms are often used interchangeably.",type:"recall"},
  {id:75,cat:"C",q:"Crown venting a trap means connecting the vent:",opts:["At the trap weir","At the top (crown) of the trap — which is generally prohibited","Below the trap","At the trap arm only"],ans:1,exp:"Crown venting (connecting at the trap's highest point) is prohibited because it creates a path for solids to enter the vent. The vent must connect at the trap arm, above the trap weir.",type:"recall"},

  // BLOCK D: Fixtures & Appliances (20)
  {id:76,cat:"D",q:"A water closet requires a minimum drain size of:",opts:["2\"","3\"","4\"","1-1/2\""],ans:1,exp:"Water closets (toilets) require a minimum 3\" drain. The closet bend connects the flange to the 3\" branch drain. This is a non-negotiable code requirement.",type:"recall"},
  {id:77,cat:"D",q:"The maximum flow rate for a residential lavatory faucet per water conservation codes is:",opts:["5.7 L/min (1.5 GPM)","8.3 L/min (2.2 GPM)","11.4 L/min (3.0 GPM)","No limit"],ans:0,exp:"Water conservation codes limit lavatory faucets to approximately 5.7 L/min (1.5 GPM) or less. Kitchen faucets are typically limited to 8.3 L/min (2.2 GPM).",type:"recall"},
  {id:78,cat:"D",q:"An anti-scald valve on a shower is required to prevent water temperature from exceeding:",opts:["38°C (100°F)","49°C (120°F)","60°C (140°F)","No requirement"],ans:1,exp:"Anti-scald (thermostatic mixing or pressure-balanced) valves are required on showers/tubs to limit output to 49°C (120°F) maximum, preventing scalding injuries.",type:"recall"},
  {id:79,cat:"D",q:"A floor drain requires:",opts:["No trap","A trap with trap seal maintained by a trap primer or trap seal primer device","Only a grate","Direct sewer connection"],ans:1,exp:"Floor drains must have traps. Since they're rarely used, the seal evaporates. Trap primers (automatic water feed) or trap seal devices maintain the seal against sewer gas.",type:"recall"},
  {id:80,cat:"D",q:"A dishwasher drain must connect with:",opts:["Direct connection to the disposal","An air gap or high loop to prevent backflow of sink drain water into the dishwasher","A P-trap of its own","A floor drain"],ans:1,exp:"An air gap device (preferred) or a high loop prevents dirty sink water from siphoning back into the dishwasher. The dishwasher drain connects to the disposal or tailpiece.",type:"procedure"},
  {id:81,cat:"D",q:"What is the rough-in measurement for a standard water closet?",opts:["10\"","12\" (305mm) from finished wall to centre of closet flange","14\"","8\""],ans:1,exp:"Standard rough-in is 12\" (305mm) from the finished wall to the centre of the closet bolt holes. 10\" and 14\" rough-ins exist but are less common.",type:"recall"},
  {id:82,cat:"D",q:"A washing machine standpipe must be what minimum size?",opts:["1-1/4\"","2\" diameter, minimum 18\" tall, maximum 30\" tall","3\"","1-1/2\""],ans:1,exp:"Standpipe: minimum 2\" diameter, 18-30\" (450-750mm) above the trap. This provides an air break and prevents suds/water overflow while accommodating the pump's discharge.",type:"recall"},
  {id:83,cat:"D",q:"What type of valve is required for a water heater?",opts:["Gate valve only","Temperature and Pressure (T&P) relief valve","Check valve only","Ball valve only"],ans:1,exp:"T&P relief valves are life-safety devices. They open if temperature exceeds 99°C (210°F) or pressure exceeds 1035 kPa (150 PSI), preventing tank explosion.",type:"recall"},
  {id:84,cat:"D",q:"The T&P valve discharge pipe must terminate:",opts:["Into the sewer","Within 150mm of the floor or to an approved indirect waste receptor, with no valves or restrictions","Into a bucket","Outside the building always"],ans:1,exp:"T&P discharge must: terminate within 150mm of floor or to indirect waste, be same size as valve outlet, pitch downward, have no valves/restrictions, and be visible for monitoring.",type:"procedure"},
  {id:85,cat:"D",q:"A bidet requires what type of backflow protection?",opts:["None","Vacuum breaker or other approved backflow preventer on the supply","Air gap only","Check valve only"],ans:1,exp:"Bidets present a high-hazard cross-connection (submerged outlet). They require a vacuum breaker or approved backflow device on the supply to prevent contamination of potable water.",type:"recall"},
  {id:86,cat:"D",q:"An indirect waste connection means:",opts:["Pipe connected directly to the drain","A drain that discharges through an air gap into a receptor (no direct physical connection to the sewer)","A hidden drain","A temporary drain"],ans:1,exp:"Indirect waste uses an air gap between the fixture drain and the receptor (floor drain, floor sink). Required for food equipment, ice machines, HVAC condensate, and similar to prevent backflow.",type:"recall"},
  {id:87,cat:"D",q:"A garbage disposal (garburator) connects to:",opts:["The vent","The sink drain tailpiece — between the basket strainer and the P-trap","The water supply","A separate drain stack"],ans:1,exp:"The disposal replaces the standard tailpiece. It grinds food waste and discharges to the continuous waste connection above the P-trap. The dishwasher often connects to the disposal.",type:"recall"},
  {id:88,cat:"D",q:"When mounting a wall-hung lavatory, the carrier must support:",opts:["Just the sink weight","The sink plus a person leaning on it — typically rated for 200+ lbs","Only water weight","No structural requirement"],ans:1,exp:"Wall-hung fixture carriers must be structurally secured to framing and rated to support the fixture plus applied loads (someone leaning/sitting on it). Carriers bolt to the wall structure.",type:"recall"},
  {id:89,cat:"D",q:"A shower receptor (base) must have what minimum drain size?",opts:["1-1/4\"","2\"","3\"","1-1/2\""],ans:1,exp:"Shower drains must be minimum 2\" per code. This ensures adequate flow capacity for the shower head flow rate without flooding the receptor.",type:"recall"},
  {id:90,cat:"D",q:"Emergency eyewash/shower stations require:",opts:["Hot water only","Tepid water (16-38°C) supply capable of flowing for 15 minutes minimum","Cold water only","No specific requirement"],ans:1,exp:"ANSI Z358.1: tepid water (16-38°C/60-100°F), minimum 15 minutes flow for eyewash, 20 minutes for drench shower. Located within 10 seconds of hazard.",type:"recall"},
  {id:91,cat:"D",q:"Accessible (barrier-free) fixtures must comply with:",opts:["No standards","CSA B651 and local building code accessibility requirements for height, clearance, and controls","Only aesthetics","Only commercial codes"],ans:1,exp:"Barrier-free fixtures: specific mounting heights, clear floor space, knee clearance, lever handles (not knobs), and insulated P-traps per CSA B651 and local accessibility codes.",type:"recall"},
  {id:92,cat:"D",q:"A bathtub waste and overflow assembly drain size is typically:",opts:["1-1/4\"","1-1/2\"","2\"","3\""],ans:1,exp:"Bathtub drains are 1-1/2\". The waste and overflow connects the drain to the overflow plate, with a stopper mechanism. The 1-1/2\" trap connects below.",type:"recall"},
  {id:93,cat:"D",q:"When installing a water heater, the cold water inlet must have:",opts:["Nothing special","A shut-off valve for isolation and a dielectric union if connecting dissimilar metals","Only a check valve","A PRV"],ans:1,exp:"Cold inlet needs: a shut-off valve (isolation for maintenance), and a dielectric union if connecting copper to steel nipples on the heater. Also required: T&P valve, expansion tank if closed system.",type:"procedure"},
  {id:94,cat:"D",q:"A urinal flush valve requires a minimum supply pipe size of:",opts:["1/2\"","3/4\"","1\"","1-1/4\""],ans:2,exp:"Flush valves (as opposed to flush tanks) require higher instantaneous flow. Urinal flush valves need minimum 3/4\" supply, while water closet flush valves need minimum 1\" supply.",type:"recall"},
  {id:95,cat:"D",q:"A commercial kitchen 3-compartment sink requires:",opts:["Standard residential drain","Properly sized drain with indirect waste to a grease interceptor","No special requirements","Only one compartment drained"],ans:1,exp:"Commercial kitchen sinks drain indirectly through an air gap to a grease interceptor, then to the sanitary sewer. This prevents grease from entering the municipal system directly.",type:"recall"},

  // BLOCK E: Hydronic Heating & Gas (22)
  {id:96,cat:"E",q:"A hydronic heating system circulates what medium?",opts:["Air","Water (or water/glycol mixture) to transfer heat from boiler to radiators","Refrigerant","Steam only"],ans:1,exp:"Hydronic systems circulate heated water through pipes to radiators, fan coils, or in-floor tubing. Glycol is added for freeze protection in systems exposed to freezing temperatures.",type:"recall"},
  {id:97,cat:"E",q:"The expansion tank in a hydronic system accommodates:",opts:["Extra water supply","Volume change as water expands when heated","Air supply","Gas pressure"],ans:1,exp:"Water expands ~4% when heated from 4°C to 100°C. The expansion tank (diaphragm type) absorbs this volume increase, preventing dangerous pressure buildup in the closed system.",type:"recall"},
  {id:98,cat:"E",q:"In-floor radiant heating tubing is typically made of:",opts:["Copper only","PEX (cross-linked polyethylene)","Cast iron","Steel"],ans:1,exp:"PEX is the standard for in-floor radiant: flexible, corrosion-resistant, handles thermal expansion, and long continuous runs minimize joints in the slab.",type:"recall"},
  {id:99,cat:"E",q:"A boiler relief valve is set to:",opts:["Any pressure","30 PSI (207 kPa) for residential hot water boilers (or the boiler's rated pressure)","100 PSI","5 PSI"],ans:1,exp:"The relief valve must be set at or below the boiler's rated working pressure (typically 30 PSI for residential). It's a critical safety device preventing explosion.",type:"recall"},
  {id:100,cat:"E",q:"Natural gas pipe sizing depends on:",opts:["Only the pipe colour","BTU demand of all appliances, pipe length, available pressure, and specific gravity of gas","Only pipe length","Only the number of appliances"],ans:1,exp:"Gas pipe sizing uses tables correlating: total BTU/h demand, total developed length (longest run), inlet pressure, allowable pressure drop, and gas specific gravity.",type:"procedure"},
  {id:101,cat:"E",q:"A gas pipe leak test uses what medium?",opts:["Water","Air or nitrogen at specified pressure for specified duration","Oxygen","The gas itself"],ans:1,exp:"Gas piping is tested with air or inert gas (nitrogen) at the test pressure specified by code. NEVER use oxygen or the fuel gas itself for testing. Soap solution finds individual leaks.",type:"procedure"},
  {id:102,cat:"E",q:"What is the minimum size gas pipe for a residential furnace?",opts:["Depends on BTU rating and pipe run length per gas code sizing tables","Always 1/2\"","Always 3/4\"","Always 1\""],ans:0,exp:"Gas pipe sizing is always calculated from tables — never assumed. A 100,000 BTU furnace 30 feet from the meter may need 3/4\" while the same furnace at 100 feet may need 1\". Always calculate.",type:"procedure"},
  {id:103,cat:"E",q:"A gas connector (flex line) to an appliance must be:",opts:["Any length","Approved type, accessible, maximum length per code, and not through walls/floors","Homemade from garden hose","Hidden in the wall"],ans:1,exp:"Gas connectors must be CSA-approved, accessible full length, not penetrate walls/floors/ceilings, and within maximum length limits. Older uncoated brass connectors must be replaced.",type:"recall"},
  {id:104,cat:"E",q:"Black steel pipe for gas is joined by:",opts:["Solvent cement","Threading with approved pipe thread compound or PTFE tape rated for gas","Soldering","Compression fittings"],ans:1,exp:"Black steel gas pipe: threaded joints with gas-rated thread compound or yellow PTFE tape (gas rated). Regular Teflon tape (white) is NOT approved for gas. All joints must be accessible.",type:"procedure"},
  {id:105,cat:"E",q:"A sediment trap (drip leg) on a gas line is installed:",opts:["At the meter only","At the inlet of each gas appliance to catch moisture and debris","On the vent","On the flue only"],ans:1,exp:"Sediment traps (tee with capped nipple) are installed at each appliance inlet to catch moisture, dirt, and pipe scale before it enters the gas valve. Minimum 3\" deep.",type:"recall"},
  {id:106,cat:"E",q:"Combustion air for a gas appliance is required because:",opts:["It cools the appliance","Gas combustion consumes oxygen — insufficient air causes incomplete combustion and carbon monoxide","It's decorative","It silences the burner"],ans:1,exp:"Gas combustion needs oxygen. Without adequate combustion air, incomplete combustion produces deadly carbon monoxide (CO). Codes specify air opening sizes based on appliance BTU rating.",type:"recall"},
  {id:107,cat:"E",q:"A hydronic zone valve controls:",opts:["Gas flow","Water flow to individual heating zones for temperature control","Electrical power","Air flow"],ans:1,exp:"Zone valves open/close to allow or stop hot water flow to specific heating zones, controlled by individual thermostats. This provides room-by-room temperature control.",type:"recall"},
  {id:108,cat:"E",q:"A mixing valve on a hydronic system controls:",opts:["Gas mixture","Water temperature to the distribution system by blending supply and return water","Air mixture","Refrigerant flow"],ans:1,exp:"Mixing valves blend hot supply water with cooler return water to deliver the correct temperature to the zone (e.g., in-floor radiant needs ~35-45°C, not the 82°C boiler output).",type:"recall"},
  {id:109,cat:"E",q:"CSST (Corrugated Stainless Steel Tubing) for gas requires:",opts:["No special grounding","Bonding to the electrical grounding system per manufacturer and code requirements","Only plastic fittings","Burial underground"],ans:1,exp:"CSST must be bonded to the building's electrical grounding system to protect against lightning-induced voltage that can puncture the thin stainless steel wall. Critical safety requirement.",type:"recall"},
  {id:110,cat:"E",q:"Air bleeding from a hydronic system is necessary to:",opts:["Add oxygen","Remove trapped air that causes noise, reduces heat output, and can cause pump cavitation","Increase pressure","Cool the water"],ans:1,exp:"Trapped air creates noise (gurgling), blocks water flow (cold radiators), and can cause circulator pump damage (cavitation). Air vents and bleed valves at high points remove trapped air.",type:"recall"},
  {id:111,cat:"E",q:"A gas meter measures gas consumption in:",opts:["Litres","Cubic metres (m³) or cubic feet (ft³)","PSI","BTU directly"],ans:1,exp:"Gas meters measure volume (m³ or ft³) of gas consumed. The utility converts volume to energy (BTU or GJ) using the gas heating value for billing purposes.",type:"recall"},
  {id:112,cat:"E",q:"Glycol in a hydronic system requires the circulator pump to be:",opts:["Smaller","Sized larger because glycol is more viscous than water, increasing friction loss","The same size","Turned off"],ans:1,exp:"Glycol is thicker (more viscous) than water and has lower heat capacity. Pump must be sized for increased friction losses. System also needs more flow to carry the same amount of heat.",type:"recall"},
  {id:113,cat:"E",q:"Category I gas venting (natural draft) uses which type of vent material?",opts:["PVC","Type B vent (double-wall) or lined masonry chimney","Single-wall steel always","No vent needed"],ans:1,exp:"Category I (negative pressure, non-condensing): Type B vent or ULC-listed lined chimney. Category IV (condensing) appliances use PVC or CPVC vent (positive pressure, acidic condensate).",type:"recall"},
  {id:114,cat:"E",q:"A condensing boiler achieves higher efficiency by:",opts:["Burning more gas","Extracting additional heat from flue gases by condensing water vapour","Running faster","Using larger pipes"],ans:1,exp:"Condensing boilers cool flue gases below the dew point (~55°C), condensing water vapour and recovering its latent heat. This achieves 90-98% efficiency vs 80-85% for non-condensing.",type:"recall"},
  {id:115,cat:"E",q:"The minimum clearance from a gas vent to a window or air intake is:",opts:["No clearance needed","As specified by code — typically 300mm-1800mm depending on vent type and appliance","Directly adjacent is fine","3 metres always"],ans:1,exp:"Clearances vary by vent type, appliance category, and BTU rating. Codes specify minimum distances to prevent flue gases from re-entering the building through windows or air intakes.",type:"recall"},
  {id:116,cat:"E",q:"A backflow preventer on a boiler fill valve prevents:",opts:["Boiler from overfilling","Boiler water from contaminating the potable water supply","Heat from escaping","Gas from leaking"],ans:1,exp:"Boiler water contains chemicals (treatment, corrosion products) that are non-potable. The backflow preventer on the fill line prevents this contaminated water from flowing back into drinking water.",type:"recall"},
  {id:117,cat:"E",q:"A gas appliance shut-off valve must be:",opts:["Hidden","Within 1.8m (6 ft) of the appliance and accessible without moving the appliance","In another room","At the meter only"],ans:1,exp:"Individual shut-off valves are required within 1.8m of each gas appliance, accessible without moving the appliance. This allows quick isolation in emergencies.",type:"recall"},

  // BLOCK F: Private Sewage & Water Systems (18)
  {id:118,cat:"F",q:"A septic tank's primary function is:",opts:["Complete sewage treatment","Settle solids and partially decompose organic matter through anaerobic digestion","Store water","Pump sewage uphill"],ans:1,exp:"Septic tanks separate solids (settle to bottom as sludge), allow grease to float (scum layer), and begin anaerobic decomposition. Effluent then flows to the absorption field.",type:"recall"},
  {id:119,cat:"F",q:"A septic tank must be pumped out when the sludge level reaches:",opts:["Any level","1/3 of the liquid depth (typically every 3-5 years for residential)","Only when full","Never"],ans:1,exp:"Pump when sludge reaches 1/3 of liquid depth or scum layer approaches the outlet. Residential tanks are typically pumped every 3-5 years depending on tank size and household size.",type:"recall"},
  {id:120,cat:"F",q:"The leaching bed (absorption field) treats effluent by:",opts:["Chemical treatment","Distributing effluent through perforated pipe into soil where bacteria complete treatment","Evaporation only","UV treatment"],ans:1,exp:"Effluent percolates through gravel and into native soil where aerobic bacteria in the biomat complete treatment. Soil type and percolation rate determine field sizing.",type:"recall"},
  {id:121,cat:"F",q:"A percolation (perc) test determines:",opts:["Water taste","The soil's ability to absorb liquid — used to size the leaching bed","Soil colour","Soil temperature"],ans:1,exp:"Perc tests measure how fast water drains through the soil (minutes per inch). Sandy soil = fast (smaller field). Clay = slow (larger field or alternate system may be needed).",type:"recall"},
  {id:122,cat:"F",q:"Minimum setback distance from a septic tank to a well is typically:",opts:["3m (10 ft)","15m (50 ft) — varies by jurisdiction","1m (3 ft)","30m (100 ft) is typical for the leaching bed"],ans:1,exp:"Setback distances protect water sources from contamination. Tank to well: typically 15m minimum. Leaching bed to well: typically 15-30m. Always verify with local regulations.",type:"recall"},
  {id:123,cat:"F",q:"A holding tank differs from a septic tank in that:",opts:["It's the same thing","A holding tank has no outlet — all sewage is stored for periodic pump-out","It's larger","It treats the sewage completely"],ans:1,exp:"Holding tanks are sealed vessels with no outlet or field. All contents must be pumped and hauled to a treatment facility. Used where soil conditions don't allow a conventional septic system.",type:"recall"},
  {id:124,cat:"F",q:"A dug well is typically:",opts:["Very deep","Shallow (less than 15m), large diameter, hand-dug or machine-excavated, lined with casing","Always artesian","A bored well"],ans:1,exp:"Dug wells are shallow, large diameter wells. They're susceptible to surface contamination and seasonal fluctuation. Drilled wells are deeper and generally safer.",type:"recall"},
  {id:125,cat:"F",q:"A submersible well pump is installed:",opts:["On the ground surface","Below the water level inside the well casing","In the basement","On the roof"],ans:1,exp:"Submersible pumps are installed below the water level in the well, pushing water up. They're quieter and more efficient than jet pumps for deeper wells.",type:"recall"},
  {id:126,cat:"F",q:"A pressure tank in a well system:",opts:["Filters water","Maintains system pressure, reduces pump cycling, and provides reserve water","Heats water","Treats bacteria"],ans:1,exp:"Pressure tanks store pressurized water so the pump doesn't start every time a faucet opens. The air bladder/diaphragm maintains pressure. Reduces pump wear and provides consistent pressure.",type:"recall"},
  {id:127,cat:"F",q:"Well water must be tested for:",opts:["Nothing","Bacteria (total coliform/E.coli), nitrates, and other contaminants as required","Only colour","Only taste"],ans:1,exp:"At minimum: bacterial testing (total coliform, E.coli) annually. Additional testing for nitrates, hardness, iron, pH, and other contaminants recommended when commissioning or if issues arise.",type:"recall"},
  {id:128,cat:"F",q:"UV water treatment kills bacteria by:",opts:["Heating the water","Exposing water to ultraviolet light that damages DNA, preventing reproduction","Chemical treatment","Filtering",""],ans:1,exp:"UV systems expose water to germicidal UV-C light (254nm wavelength), damaging microorganism DNA so they can't reproduce. Effective against bacteria, viruses, and protozoa. Requires pre-filtration for clarity.",type:"recall"},
  {id:129,cat:"F",q:"A water softener removes:",opts:["Bacteria","Calcium and magnesium (hardness minerals) through ion exchange","Chlorine","Sediment only"],ans:1,exp:"Water softeners use ion exchange resin to swap calcium/magnesium ions for sodium ions. Regeneration with salt brine restores the resin. Reduces scale buildup in pipes and fixtures.",type:"recall"},
  {id:130,cat:"F",q:"An effluent pump in a sewage system is used when:",opts:["Always","The septic tank or pump chamber is below the leaching bed elevation and gravity flow isn't possible","Never","Only for greywater"],ans:1,exp:"Effluent pumps move clarified septic effluent from a pump chamber to an elevated leaching bed when gravity flow isn't possible due to site topography.",type:"recall"},
  {id:131,cat:"F",q:"The minimum septic tank size for a 3-bedroom home is typically:",opts:["500 gallons","1000 gallons (3600L) — varies by jurisdiction","2000 gallons","250 gallons"],ans:1,exp:"Most jurisdictions: 3-bedroom home = minimum 1000 US gallons (3785L) or 3600L Canadian. Tank size increases with bedroom count. Always check local requirements.",type:"recall"},
  {id:132,cat:"F",q:"A sewage ejector pump is used in a basement bathroom when:",opts:["Always","The fixtures are below the building sewer or septic tank inlet elevation","Only with showers","Never in residential"],ans:1,exp:"When basement fixtures are below the sewer line, a sewage ejector (grinder pump) in a sealed basin collects waste and pumps it up to the gravity sewer. Requires venting and check valve.",type:"recall"},
  {id:133,cat:"F",q:"A well cap must be:",opts:["Open for ventilation","Watertight and vermin-proof to prevent surface water and contamination from entering","Removable without tools","Made of wood"],ans:1,exp:"Well caps must be sanitary — sealed against surface water, insects, and vermin. A screened vent allows pressure equalization. Damaged or loose caps are the #1 cause of well contamination.",type:"recall"},
  {id:134,cat:"F",q:"Raised bed (mound) septic systems are used when:",opts:["Always","The water table is high, bedrock is close to surface, or soil has poor percolation","The lot is flat","The house is large"],ans:1,exp:"Mound systems elevate the absorption field above the native soil when conditions (high water table, shallow bedrock, poor perc) prevent a conventional in-ground leaching bed.",type:"recall"},
  {id:135,cat:"F",q:"A foot valve on a well suction line prevents:",opts:["Freezing","Water from draining back into the well when the pump stops (maintains prime)","Contamination","Overpressure"],ans:1,exp:"Foot valves (check valves at the bottom of suction pipe) keep the suction line full of water when the pump stops, maintaining prime so the pump doesn't have to re-prime on each cycle.",type:"recall"},
];
